-- 풀스코어 '마케팅분석 > 악보통계분석' 주문수 (2026-11-03 조회, 주문수 많은 순).
-- 악보관리 목록을 이 순서대로 보여 주고, 위에서부터 PDF 를 채워 넣기 위한 값.
-- 적용 순서: sheets_types.sql → sheets_import_fullscore.sql → 이 파일.
alter table public.sheets add column if not exists fullscore_orders integer not null default 0;

-- 구름산은 풀스코어에서 옮기기 전에 먼저 등록해 둔 곡이라 상품 코드가 비어 있다 — 코드부터 채운다.
-- (맥에서 입력한 한글은 자모가 분리(NFD)돼 있을 수 있어 NFC 로 맞춰 비교)
update public.sheets set fullscore_code = '2401290007'
 where fullscore_code is null and normalize(title, NFC) = '구름산';

